import { writeFileSync } from 'node:fs';

const cases = [];
const seen = new Set();
// Use the `--a=VALUE` form so values beginning with '-' are not mistaken for
// options by argparse; both programs handle `--a=` identically for the rest.
const add = (value) => {
  const argv = ['--a=' + value];
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
};
const addRaw = (argv) => {
  const key = JSON.stringify(argv);
  if (seen.has(key)) return;
  seen.add(key);
  cases.push(argv);
};

const BS = String.fromCodePoint(0x5c); // backslash
// Every ASCII punctuation character, in string.punctuation order.
const PUNCT = ['!', '"', '#', '$', '%', '&', "'", '(', ')', '*', '+', ',', '-',
  '.', '/', ':', ';', '<', '=', '>', '?', '@', '[', BS, ']', '^', '_', '`',
  '{', '|', '}', '~'];

// ASCII whitespace: space, tab, LF, CR, VT (U+000B), FF (U+000C)
